const response = $('CLT - OFFLINE').first().json;

// ======================================================
// TRATAMENTO INICIAL
// ======================================================

if (!response) {
  return [{
    json: {
      resultado: "FALHA_API",
      motivo: "sem_resposta",
      anotacao: "A API não retornou resposta."
    }
  }];
}

if (response.erro === true) {
  return [{
    json: {
      resultado: "FALHA_API",
      motivo: "base_offline_indisponivel",
      anotacao: response.mensagem || "Base offline indisponível no momento."
    }
  }];
}

const dados = response.dados || [];

if (dados.length === 0) {
  return [{
    json: {
      resultado: "SEM_DADOS",
      motivo: "sem_dados_base_offline",
      nome: null,
      dataNascimento: null,
      nomeMae: null,
      sexo: null,
      anotacao: "Nenhum dado encontrado na base offline para este CPF."
    }
  }];
}

// ======================================================
// FUNÇÕES
// ======================================================

function numero(valor) {
  return parseFloat(String(valor || 0).replace(",", ".")) || 0;
}

function calcularMeses(dataAdmissao) {
  if (!dataAdmissao) return 0;
  const admissao = new Date(dataAdmissao);
  const hoje = new Date();
  let meses = (hoje.getFullYear() - admissao.getFullYear()) * 12;
  meses += hoje.getMonth() - admissao.getMonth();
  return meses;
}

function formatarTempoVinculo(meses) {
  if (meses <= 0) return "0 meses";
  const anos = Math.floor(meses / 12);
  const resto = meses % 12;
  if (anos > 0 && resto > 0) return `${anos} ano${anos > 1 ? "s" : ""} e ${resto} meses`;
  if (anos > 0) return `${anos} ano${anos > 1 ? "s" : ""}`;
  return `${resto} meses`;
}

// ======================================================
// DADOS GERAIS
// ======================================================

const nomeCliente = dados[0]?.nome || "Não informado";
const cpf = dados[0]?.cpf || "Não informado";
const dataNascimento = dados[0]?.dataNascimento || null;
const nomeMae = dados[0]?.nomeMae || null;
const sexo = dados[0]?.sexo_descricao || null;

const cabecalho = `Cliente: ${nomeCliente} | CPF: ${cpf}`;

const updatedAt = dados.reduce((maisRecente, v) => {
  if (!v.updated_at) return maisRecente;
  return !maisRecente || new Date(v.updated_at) > new Date(maisRecente)
    ? v.updated_at
    : maisRecente;
}, null);

const rodape = `\n\nBase atualizada em: ${updatedAt}`;

// ======================================================
// FLAGS
// ======================================================

const possui_margem_disponivel = dados.some(v =>
  numero(v.valorMargemDisponivel) > 50
);

const possui_vinculo_1_ano_com_margem = dados.some(v =>
  calcularMeses(v.dataAdmissao) >= 12 &&
  numero(v.valorMargemDisponivel) > 50
);

const possui_vinculo_recente_com_margem = dados.some(v =>
  calcularMeses(v.dataAdmissao) < 3 &&
  numero(v.valorMargemDisponivel) > 50
);

const flags = {
  possui_margem_disponivel,
  possui_vinculo_1_ano_com_margem
};

const identificacao = { nomeMae, sexo };

// ======================================================
// TODOS OS VÍNCULOS
// ======================================================

const todosVinculos = dados.map(v => {
  const meses = calcularMeses(v.dataAdmissao);
  return `• Matrícula: ${v.matricula} | Margem: R$ ${numero(v.valorMargemDisponivel).toFixed(2)} | Admissão: ${v.dataAdmissao} | Tempo: ${formatarTempoVinculo(meses)}`;
}).join('\n');

// ======================================================
// FILTRO 3 MESES
// ======================================================

const vinculosValidos = dados.filter(v =>
  calcularMeses(v.dataAdmissao) >= 3
);

if (vinculosValidos.length === 0) {
  return [{
    json: {
      resultado: "NAO_APROVADO",
      motivo: "sem_vinculo_3_meses",
      nome: nomeCliente,
      dataNascimento,
      ...identificacao,
      ...flags,
      anotacao: `${cabecalho}\n\nCliente não possui vínculos com tempo mínimo de 3 meses.\n\nTodos os vínculos encontrados:\n${todosVinculos}${rodape}`
    }
  }];
}

// ======================================================
// MARGEM
// ======================================================

const comMargem = vinculosValidos.filter(v =>
  numero(v.valorMargemDisponivel) > 50
);

if (comMargem.length === 0) {

  if (possui_vinculo_recente_com_margem) {
    return [{
      json: {
        resultado: "NAO_APROVADO",
        motivo: "vinculo_recente_com_margem",
        nome: nomeCliente,
        dataNascimento,
        ...identificacao,
        ...flags,
        anotacao: `${cabecalho}\n\nCliente possui margem disponível, porém apenas em vínculo recente com menos de 3 meses.\n\nTodos os vínculos encontrados:\n${todosVinculos}${rodape}`
      }
    }];
  }

  return [{
    json: {
      resultado: "NAO_APROVADO",
      motivo: "sem_margem",
      nome: nomeCliente,
      dataNascimento,
      ...identificacao,
      ...flags,
      anotacao: `${cabecalho}\n\nCliente não possui vínculos aptos com margem acima de R$ 50,00.\n\nTodos os vínculos encontrados:\n${todosVinculos}${rodape}`
    }
  }];
}

// ======================================================
// ELEGIBILIDADE FACTA
// ======================================================

const elegiveisComMargem = comMargem.filter(v =>
  v.elegivel === "1"
);

if (elegiveisComMargem.length === 0) {

  const maiorMargem = Math.max(
    ...comMargem.map(v => numero(v.valorMargemDisponivel))
  );

  const detalhes = comMargem.map(v =>
    `• Matrícula: ${v.matricula} | Margem: R$ ${numero(v.valorMargemDisponivel).toFixed(2)} | Elegível: ${v.elegivel} | Motivo: ${v.motivoInelegibilidade_descricao || "Não informado"}`
  ).join('\n');

  return [{
    json: {
      resultado: "NAO_APROVADO",
      motivo: "nao_elegivel_facta",
      nome: nomeCliente,
      dataNascimento,
      ...identificacao,
      ...flags,
      anotacao: `${cabecalho}\n\nCliente possui margem, porém não possui vínculo elegível na Facta.\n\nVínculos analisados:\n${detalhes}\n\nMaior margem encontrada: R$ ${maiorMargem.toFixed(2)}${rodape}`
    }
  }];
}

// ======================================================
// APROVADO
// ======================================================

return elegiveisComMargem.map(v => {
  const meses = calcularMeses(v.dataAdmissao);
  return {
    json: {
      rota: 1,
      cpf: v.cpf,
      nome: v.nome,
      dataNascimento: v.dataNascimento,
      ...identificacao,
      matricula: v.matricula,
      margem: numero(v.valorMargemDisponivel),
      valor_total_vencimentos: numero(v.valorTotalVencimentos),
      valor_base_margem: numero(v.valorBaseMargem),
      dataAdmissao: v.dataAdmissao,
      nome_empregador: v.nomeEmpregador,
      meses_vinculo: meses,
      tempo_vinculo_formatado: formatarTempoVinculo(meses),
      qt_emprestimos_ativos: v.qtdEmprestimosAtivosSuspensos,
      ...flags,
      base_atualizada_em: updatedAt
    }
  };
});

