const tentativas = 5;
const items = [];

for (let i = 1; i <= tentativas; i++) {
  items.push({ json: { tentativa: i } });
}

return items;

const item = $input.first().json;

function tentar(fn) {
  try { return fn(); } catch (e) { return undefined; }
}

// ======================================================
// CONFIGURAÇÃO (só mexer aqui)
// ======================================================

// Só trabalha com tabela GOLD COM seguro. Se a Facta devolver GOLD com valor_seguro = 0,
// o cliente cai em "sem_tabela_gold_com_seguro". Pra liberar tabela sem seguro (emergência),
// troque para false.
const EXIGIR_SEGURO = true;

// Comissão mínima (%) aceita. 0 = aceita qualquer uma (as piores ficam só como último recurso
// no ranking). Ex.: 4 = nunca oferece tabela que pague menos de 4%.
const COMISSAO_MINIMA = 0;

// ======================================================
// TABELA GOLD (COM seguro) — vigência 23/10/2026
// Fonte: "Crédito do Trabalhador - Divulgação 23/10/2026".
// A tabela nova NÃO tem mais faixa por tempo de vínculo: são tiers (PREMIUM > PLUS > POWER > PRIME).
// comissao = Remuneração 1 (%) | comissao2 = Remuneração 2 (%), usada só como desempate.
// Pra atualizar: troque as linhas abaixo (código / tier / prazo / comissão).
// ======================================================
const COMISSOES_GOLD = [
  { codigo: '71056', tier: 'PREMIUM', prazo: 24, comissao: 5.50, comissao2: 0 },
  { codigo: '71064', tier: 'PREMIUM', prazo: 36, comissao: 6.00, comissao2: 0.50 },
  { codigo: '71072', tier: 'PREMIUM', prazo: 48, comissao: 6.00, comissao2: 1.00 },
  { codigo: '71080', tier: 'PREMIUM', prazo: 60, comissao: 6.00, comissao2: 2.00 },
  { codigo: '71099', tier: 'PLUS',    prazo: 24, comissao: 3.50, comissao2: 0 },
  { codigo: '71102', tier: 'PLUS',    prazo: 36, comissao: 4.50, comissao2: 0 },
  { codigo: '71110', tier: 'PLUS',    prazo: 48, comissao: 5.00, comissao2: 0 },
  { codigo: '71129', tier: 'PLUS',    prazo: 60, comissao: 6.00, comissao2: 0 },
  { codigo: '71137', tier: 'POWER',   prazo: 24, comissao: 3.50, comissao2: 0 },
  { codigo: '71145', tier: 'POWER',   prazo: 36, comissao: 4.25, comissao2: 0 },
  { codigo: '71153', tier: 'POWER',   prazo: 48, comissao: 4.50, comissao2: 0 },
  { codigo: '71170', tier: 'PRIME',   prazo: 24, comissao: 3.00, comissao2: 0 },
  { codigo: '71188', tier: 'PRIME',   prazo: 36, comissao: 4.00, comissao2: 0 },
  { codigo: '71196', tier: 'PRIME',   prazo: 48, comissao: 4.50, comissao2: 0 },
];

const PRAZOS = [24, 36, 48, 60];

// ======================================================
// DADOS DO CLIENTE
// ======================================================

const prazoMaximo = Number(item.prazo_maximo_disponivel) || 0;

// meses de vínculo: o item vindo da política NÃO traz esse campo (antes caía em 0).
const meses = Number(
  tentar(() => $('LOOP VINCULOS').item.json.meses_vinculo) ??
  tentar(() => $('ANALISA VÍNCULOS').item.json.meses_vinculo) ??
  item.meses_vinculo ??
  0
) || 0;

function faixaDoCliente(m) {
  if (m >= 121) return 'acima_10anos';
  if (m >= 61) return 'faixa_61_120';
  if (m >= 36) return 'faixa_36_60';
  if (m >= 24) return 'faixa_24_35';
  return 'abaixo_24';
}

const faixaCliente = faixaDoCliente(meses);

// ======================================================
// RANKING POR PRAZO (maior comissão primeiro)
// Se a Facta não devolver o tier melhor pro cliente, cai pro próximo da lista.
// ======================================================

const rankingGoldPorPrazo = {};

for (const prazo of PRAZOS) {
  if (prazo > prazoMaximo) continue;

  const lista = COMISSOES_GOLD
    .filter(r => r.prazo === prazo)
    .filter(r => r.comissao >= COMISSAO_MINIMA)
    .sort((x, y) => (y.comissao - x.comissao) || (y.comissao2 - x.comissao2));

  if (lista.length) {
    rankingGoldPorPrazo[prazo] = lista.map(r => ({
      codigo: r.codigo,
      tier: r.tier,
      comissao: r.comissao,
    }));
  }
}

const codigosGoldPorPrazo = {};
for (const [prazo, lista] of Object.entries(rankingGoldPorPrazo)) {
  codigosGoldPorPrazo[prazo] = lista.map(r => r.codigo);
}

const codigosValidosGold = [...new Set(Object.values(codigosGoldPorPrazo).flat())];

return [{
  json: {
    ...item,

    meses_vinculo: meses,
    faixa_cliente: faixaCliente,
    prazo_informado: prazoMaximo,

    tabela_nome: 'NOVO GOLD',
    exigir_seguro: EXIGIR_SEGURO,

    // [{codigo, tier, comissao}] por prazo, já ordenado: o primeiro é o preferido
    ranking_gold_por_prazo: rankingGoldPorPrazo,
    codigos_gold_por_prazo: codigosGoldPorPrazo,
    codigos_validos_gold: codigosValidosGold,
  }
}];

const vinculosElegiveis = $('ANALISA VÍNCULOS').all();
const nome = vinculosElegiveis[0]?.json.nome || 'Não informado';
const cpf = vinculosElegiveis[0]?.json.cpf || 'Não informado';
const dataNascimento = vinculosElegiveis[0]?.json.dataNascimento || null;
const baseAtualizadaEm = vinculosElegiveis[0]?.json.base_atualizada_em || 'Não informado';
const possuiVinculo1AnoComMargem = vinculosElegiveis[0]?.json.possui_vinculo_1_ano_com_margem || false;
const possuiMargemDisponivel = vinculosElegiveis[0]?.json.possui_margem_disponivel || false;
const nomeMae = vinculosElegiveis[0]?.json.nomeMae || null;
const sexo = vinculosElegiveis[0]?.json.sexo || null;

const identificacao = { nomeMae, sexo };

const detalhes = vinculosElegiveis.map(v =>
  `• Matrícula: ${v.json.matricula} | Margem: R$ ${parseFloat(v.json.margem || 0).toFixed(2)} | Tempo: ${v.json.tempo_vinculo_formatado}`
).join('\n');

return [{
  json: {
    resultado: "NAO_APROVADO",
    motivo: "fora_politica_credito",
    nome,
    dataNascimento,
    ...identificacao,
    possui_vinculo_1_ano_com_margem: possuiVinculo1AnoComMargem,
    possui_margem_disponivel: possuiMargemDisponivel,
    anotacao: `Cliente: ${nome} | CPF: ${cpf}\n\nVínculos elegíveis encontrados, porém todos ficaram fora da política de crédito da Facta.\n\nVínculos analisados:\n${detalhes}\n\nAs margens permanecem válidas — fluxo encaminhado para consulta em outros bancos.\n\nBase atualizada em: ${baseAtualizadaEm}`
  }
}];

const response = $('4-Consulta de Operações Disponíveis').item.json;

const analise = $('ANALISA VÍNCULOS').item.json;
const tabelaDefinida = $('definir tabela').item.json;
const prepPrestacao = $('PREPARA BUSCA PRESTACAO OFICIAL').item.json;
const rawParcelaMaxima = $('BUSCA PRESTACAO OFICIAL FACTA').item.json || {};
const politica = $('BUSCA PRAZO MAXIMO').item.json || {};

const nomeCliente = analise.nome;
const cpfCliente = analise.cpf;
const matricula = analise.matricula;
const nomeEmpregador = analise.nome_empregador;
const dataAdmissao = analise.dataAdmissao;
const dataNascimento = analise.dataNascimento || null;
const tempoVinculo = analise.tempo_vinculo_formatado;
const margem = Number(analise.margem || 0);
const emprestimosAtivos = analise.qt_emprestimos_ativos;
const baseAtualizadaEm = analise.base_atualizada_em;

// Identificação (nome da mãe, sexo) sempre presente na saída
const identificacao = {
  nomeMae: analise.nomeMae || null,
  sexo: analise.sexo || null,
};

const tabelaNome = tabelaDefinida.tabela_nome || 'NOVO GOLD';
const ranking = tabelaDefinida.ranking_gold_por_prazo || {};
const exigirSeguro = tabelaDefinida.exigir_seguro !== false;

const prazoMaximo = Number(politica.prazo_maximo_disponivel || 0);
const valorMaximo = Number(politica.valor_maximo_disponivel || 0);

const possuiVinculo1AnoComMargem = analise.possui_vinculo_1_ano_com_margem || false;
const possuiMargemDisponivel = analise.possui_margem_disponivel || false;

function moneyToNumber(valor) {
  if (valor === null || valor === undefined || valor === '') return 0;
  if (typeof valor === 'number') return valor;

  let texto = String(valor).trim();
  texto = texto.replace(/[^\d,.-]/g, '');

  if (texto.includes(',') && texto.includes('.')) {
    texto = texto.replace(/\./g, '').replace(',', '.');
  } else if (texto.includes(',')) {
    texto = texto.replace(',', '.');
  }

  const numero = Number(texto);
  return Number.isFinite(numero) ? numero : 0;
}

function formatBRL(valor) {
  return Number(valor || 0).toLocaleString('pt-BR', {
    minimumFractionDigits: 2,
    maximumFractionDigits: 2,
  });
}

function numeroTabela(nomeTabela) {
  const match = String(nomeTabela || '').trim().match(/^(\d+)/);
  return match ? match[1] : '';
}

const cabecalhoVendedor =
  `👤 Cliente: ${nomeCliente}\n` +
  `🆔 CPF: ${cpfCliente}\n` +
  `📄 Matrícula: ${matricula}\n` +
  `🏢 Empregador: ${nomeEmpregador}\n` +
  `📅 Data de Admissão: ${dataAdmissao}\n` +
  `⏳ Tempo de Vínculo: ${tempoVinculo}\n` +
  `💰 Margem Disponível: R$ ${formatBRL(margem)}\n` +
  `📊 Tabela: ${tabelaNome}\n` +
  `🏦 Banco: FACTA\n` +
  `💼 Operação: Consignado CLT\n` +
  `📋 Empréstimos Ativos: ${emprestimosAtivos}`;

// Campos comuns de toda saída que não é PRE_APROVADO
const base = {
  nome: nomeCliente,
  dataNascimento,
  ...identificacao,
  possui_vinculo_1_ano_com_margem: possuiVinculo1AnoComMargem,
  possui_margem_disponivel: possuiMargemDisponivel,
};

const rodape = `\n\nBase atualizada em: ${baseAtualizadaEm}`;

const dadosReferencia =
  `\n\n📌 Prazo máximo: ${prazoMaximo}\n📌 Valor máximo: R$ ${formatBRL(valorMaximo)}`;

// ─── 1) ERROS DA CONSULTA DE OPERAÇÕES DISPONÍVEIS ──────────────────────────

// Erros de negócio da consulta de operações.
if (response.erro === true) {
  const mensagemNegocio = response.mensagem || '';
  const msgNegocioLower = mensagemNegocio.toLowerCase();

  let motivo = 'regra_facta';
  let titulo = mensagemNegocio || 'Cliente não aprovado pela regra da Facta.';

  if (msgNegocioLower.includes('parcela em atraso')) {
    motivo = 'parcela_em_atraso';
    titulo = 'Cliente possui contrato com parcela em atraso na Facta.';
  }

  return [{
    json: {
      resultado: 'NAO_APROVADO',
      motivo,
      ...base,
      anotacao: `${cabecalhoVendedor}\n\nSTATUS DA ANÁLISE\n❌ ${titulo}\n\n${mensagemNegocio}${rodape}`,
    }
  }];
}

if (response.error) {
  const statusCode = response.error?.status || 'desconhecido';

  return [{
    json: {
      resultado: 'APROVADO_SEM_SIMULACAO',
      motivo: 'falha_api_facta',
      ...base,
      anotacao: `${cabecalhoVendedor}\n\nSTATUS DA ANÁLISE\n⚠️ Instabilidade na API da Facta (erro ${statusCode}).\nCliente pré-aprovado, mas a simulação não foi gerada automaticamente.${rodape}`,
    }
  }];
}

if (!Array.isArray(response.tabelas)) {
  return [{
    json: {
      resultado: 'APROVADO_SEM_SIMULACAO',
      motivo: 'resposta_inesperada_api',
      ...base,
      anotacao: `${cabecalhoVendedor}\n\nSTATUS DA ANÁLISE\n⚠️ Resposta inesperada da Facta, sem tabelas disponíveis.\nEncaminhar para atendente.${rodape}`,
    }
  }];
}

// ─── 2) SEM TABELA POSSÍVEL (decidido no PREPARA BUSCA PRESTACAO OFICIAL) ────

if (prepPrestacao.pular_busca_prestacao_oficial) {
  const motivoPular = prepPrestacao.motivo_pular_busca_prestacao_oficial;

  // Prazo da política (ex.: 12x) menor que qualquer tabela existente (24x+)
  if (motivoPular === 'prazo_politica_incompativel') {
    return [{
      json: {
        resultado: 'NAO_APROVADO',
        motivo: 'sem_oferta_elegivel',
        ...base,
        anotacao: `${cabecalhoVendedor}\n\nSTATUS DA ANÁLISE\n❌ Nenhuma oferta elegível: o prazo liberado pela política de crédito não comporta nenhuma tabela disponível (menor prazo: 24x).${dadosReferencia}${rodape}`,
      }
    }];
  }

  // Cliente aprovado na política, mas a Facta não devolveu GOLD com seguro
  if (motivoPular === 'sem_tabela_gold_com_seguro') {
    return [{
      json: {
        resultado: 'APROVADO_SEM_SIMULACAO',
        motivo: 'sem_tabela_gold_com_seguro',
        ...base,
        anotacao: `${cabecalhoVendedor}\n\nSTATUS DA ANÁLISE\n⚠️ A Facta não retornou nenhuma tabela GOLD com seguro para este cliente.\nEncaminhar para atendente para simulação manual.${dadosReferencia}\n📌 Tabelas retornadas pela Facta: ${JSON.stringify(prepPrestacao.codigos_retornados || {})}${rodape}`,
      }
    }];
  }
}

// ─── 3) ERRO NA BUSCA DA PRESTAÇÃO OFICIAL ──────────────────────────────────

// Se tiver prestacao_maxima, não é erro real: é justamente o dado que queremos.
if (rawParcelaMaxima.erro === true && !rawParcelaMaxima.prestacao_maxima) {
  const mensagemErro = rawParcelaMaxima.mensagem || '';
  const msgLower = mensagemErro.toLowerCase();

  if (msgLower.includes('não perturbe') || msgLower.includes('nao perturbe')) {
    return [{
      json: {
        resultado: 'NAO_APROVADO',
        motivo: 'cliente_nao_perturbe',
        ...base,
        anotacao: `${cabecalhoVendedor}\n\nSTATUS DA ANÁLISE\n🚫 Cliente registrado no Não Perturbe.\nOperação bloqueada pela Facta.${rodape}`,
      }
    }];
  }

  return [{
    json: {
      resultado: 'APROVADO_SEM_SIMULACAO',
      motivo: 'falha_busca_parcela',
      ...base,
      anotacao: `${cabecalhoVendedor}\n\nSTATUS DA ANÁLISE\n⚠️ Erro ao buscar prestação máxima: ${mensagemErro}\nEncaminhar para atendente para simulação manual.${rodape}`,
    }
  }];
}

// ─── 4) PROCESSAMENTO DAS OFERTAS ───────────────────────────────────────────

const prestacaoOficial = moneyToNumber(rawParcelaMaxima.prestacao_maxima);
const prestacaoPreparada = moneyToNumber(prepPrestacao.valor_parcela);
const parcelaReferencia = prestacaoOficial > 0 ? prestacaoOficial : prestacaoPreparada;

function posicaoNoRanking(o) {
  const lista = ranking[Number(o.prazo)] || [];
  return lista.findIndex(r => r.codigo === numeroTabela(o.tabela));
}

// Só entra oferta GOLD da allowlist (por prazo) e, se exigido, COM seguro.
// Não existe mais fallback para "qualquer tabela".
const ofertasGoldElegiveis = response.tabelas
  .map(o => {
    const posicao = posicaoNoRanking(o);
    return {
      ...o,
      codigo_base_tabela: numeroTabela(o.tabela),
      ranking_posicao: posicao,
      comissao: posicao >= 0 ? ranking[Number(o.prazo)][posicao].comissao : null,
      temSeguro: Number(o.valor_seguro || 0) > 0,
    };
  })
  .filter(o => o.ranking_posicao >= 0)
  .filter(o => !exigirSeguro || o.temSeguro);

const ofertasRecalculadas = ofertasGoldElegiveis.map(o => {
  const coeficiente = Number(o.coeficiente || 0);
  const parcelaOriginal = Number(o.parcela || 0);

  const limites = [];

  if (parcelaReferencia > 0) limites.push(parcelaReferencia);
  if (valorMaximo > 0 && coeficiente > 0) limites.push(valorMaximo * coeficiente);
  if (parcelaOriginal > 0) limites.push(parcelaOriginal);
  if (margem > 0) limites.push(Math.max(margem - 1, 0));

  const parcelaEfetiva = limites.length ? Math.min(...limites) : 0;
  const valorLiquidoEfetivo = coeficiente > 0 ? parcelaEfetiva / coeficiente : 0;

  return {
    ...o,
    parcela_original: o.parcela,
    valor_liquido_original: o.valor_liquido,
    parcela: parcelaEfetiva,
    valor_liquido: valorLiquidoEfetivo,
    prestacao_oficial_facta: prestacaoOficial || null,
  };
});

const ofertasValidas = ofertasRecalculadas.filter(o =>
  Number(o.prazo) <= prazoMaximo &&
  Number(o.prazo) >= 12 &&
  Number(o.valor_liquido) >= 500 &&
  Number(o.parcela) > 0 &&
  Number(o.coeficiente) > 0
);

// Por prazo: vence a de MAIOR comissão (menor posição no ranking).
// Empate de posição: maior valor líquido.
const prazosMapeados = {};

ofertasValidas.forEach(o => {
  const prazo = Number(o.prazo);
  const atual = prazosMapeados[prazo];

  if (!atual) {
    prazosMapeados[prazo] = o;
    return;
  }

  if (o.ranking_posicao < atual.ranking_posicao) {
    prazosMapeados[prazo] = o;
    return;
  }

  if (o.ranking_posicao === atual.ranking_posicao && Number(o.valor_liquido) > Number(atual.valor_liquido)) {
    prazosMapeados[prazo] = o;
  }
});

const ofertasDeduplicadas = Object.values(prazosMapeados)
  .sort((a, b) => Number(a.prazo) - Number(b.prazo));

if (!ofertasDeduplicadas.length) {
  return [{
    json: {
      resultado: 'NAO_APROVADO',
      motivo: 'sem_oferta_elegivel',
      ...base,
      anotacao: `${cabecalhoVendedor}\n\nSTATUS DA ANÁLISE\n❌ Nenhuma oferta elegível: o prazo/valor liberado pela política de crédito não é compatível com as tabelas disponíveis.\n\n📌 Tabela preparada: ${prepPrestacao.tabela_escolhida || '-'}\n📌 Prestação oficial: ${prestacaoOficial ? `R$ ${formatBRL(prestacaoOficial)}` : 'Não retornada'}${dadosReferencia}${rodape}`,
    }
  }];
}

let opcoes = [];

if (ofertasDeduplicadas.length === 1) {
  opcoes = [{ tipo: 'ÚNICA OPÇÃO', ...ofertasDeduplicadas[0] }];
} else if (ofertasDeduplicadas.length === 2) {
  opcoes = [
    { tipo: 'MENOR PRAZO', ...ofertasDeduplicadas[0] },
    { tipo: 'MAIOR PRAZO', ...ofertasDeduplicadas[ofertasDeduplicadas.length - 1] },
  ];
} else {
  opcoes = [
    { tipo: 'MENOR PRAZO', ...ofertasDeduplicadas[0] },
    { tipo: 'PRAZO DO MEIO', ...ofertasDeduplicadas[Math.floor(ofertasDeduplicadas.length / 2)] },
    { tipo: 'MAIOR PRAZO', ...ofertasDeduplicadas[ofertasDeduplicadas.length - 1] },
  ];
}

const temMaisDeUma = opcoes.length > 1;
const maiorValor = formatBRL(opcoes[opcoes.length - 1].valor_liquido);
const nomeFormatado = String(nomeCliente || '').split(' ')[0] || 'cliente';

// Anotação: só parcela e valor a receber (sem tabela e sem comissão), pra poder ser reaproveitada em outras automações.
// A tabela de cada oferta vai separada em `tabelas_ofertas` e em `dados_digitacao.opcoes`.
const resumoOfertas = opcoes.map(o =>
  `🔹 ${o.prazo}x de R$ ${formatBRL(o.parcela)} | Recebe: R$ ${formatBRL(o.valor_liquido)}`
).join('\n');

const tabelasOfertas = opcoes.map(o => ({
  prazo: Number(o.prazo),
  tabela: o.tabela,
  codigoTabela: String(o.codigoTabela),
}));

const anotacao =
  `${cabecalhoVendedor}\n\n` +
  `OFERTAS GERADAS\n${resumoOfertas}\n\n` +
  `📌 Prestação oficial Facta: ${prestacaoOficial ? `R$ ${formatBRL(prestacaoOficial)}` : 'Não retornada'}` +
  rodape;

let mensagem = `Boa notícia, ${nomeFormatado}! 🎉 Sua análise foi aprovada!\n\n`;
mensagem += `✅ Aprovado sem consulta ao SPC/Serasa\n`;
mensagem += `💵 Você pode receber ${temMaisDeUma ? 'até ' : ''}R$ ${maiorValor} na sua conta!\n\n`;
mensagem += temMaisDeUma
  ? 'Separei as condições disponíveis para você:\n\n'
  : 'Segue a condição disponível para você:\n\n';

mensagem += opcoes.map(o =>
  `🔹 ${o.prazo}x de R$ ${formatBRL(o.parcela)}\n💰 Valor a receber: R$ ${formatBRL(o.valor_liquido)}`
).join('\n\n');

mensagem += '\n📝 Parcelas descontadas direto no contracheque, sem impacto no seu orçamento.';
mensagem += '\n⏰ Proposta válida por tempo limitado.';
mensagem += '\n\n👉 *' + (
  temMaisDeUma
    ? 'Qual condição você prefere ou quer que eu verifique outras possibilidades?'
    : 'Deseja seguir com essa condição ou prefere que eu verifique outras possibilidades?'
) + '*';

return [{
  json: {
    resultado: 'PRE_APROVADO',
    motivo: null,
    ...base,
    anotacao,
    mensagem,
    tabelas_ofertas: tabelasOfertas,
    tabela_nome: tabelaNome,
    matricula,
    cpf: cpfCliente,
    dados_digitacao: {
      matricula,
      opcoes: opcoes.map(o => ({
        prazo: Number(o.prazo),
        parcela: Number(Number(o.parcela).toFixed(2)),
        valor_liquido: Number(Number(o.valor_liquido).toFixed(2)),
        codigoTabela: String(o.codigoTabela),
        nomeTabela: o.tabela,
        coeficiente: Number(o.coeficiente),
      })),
    },
  }
}];

function numero(valor) {
  if (valor === null || valor === undefined) return 0;

  const texto = String(valor).trim();
  if (!texto) return 0;

  if (texto.includes(',')) {
    return Number(
      texto
        .replace(/[^\d,.-]/g, '')
        .replace(/\./g, '')
        .replace(',', '.')
    ) || 0;
  }

  return Number(texto.replace(/[^\d.-]/g, '')) || 0;
}

const margem = numero($('ANALISA VÍNCULOS').item.json.margem);

if (margem <= 0) {
  return [{
    json: {
      ...$json,
      erro: true,
      mensagem: 'Margem indisponível ou inválida para calcular prestação máxima de consulta.',
      prestacao_maxima: null,
      margem_base_off: margem,
      origem_prestacao_maxima: 'margem_base_off'
    }
  }];
}

// Este valor é só para consultar as tabelas disponíveis.
// A prestação final será confirmada depois na etapa1-simulador com tabela real.
const prestacaoConsulta = Math.max(0, margem - 1);

return [{
  json: {
    ...$json,
    erro: false,
    prestacao_maxima: Number(prestacaoConsulta.toFixed(2)),
    prestacao_consulta: Number(prestacaoConsulta.toFixed(2)),
    margem_base_off: Number(margem.toFixed(2)),
    origem_prestacao_maxima: 'margem_base_off'
  }
}];

const response = $input.first().json;

const tabelas = Array.isArray(response.tabelas) ? response.tabelas : [];

const tabelaDefinida = $('definir tabela').item.json;
const ranking = tabelaDefinida.ranking_gold_por_prazo || {};
const exigirSeguro = tabelaDefinida.exigir_seguro !== false;

if (!tabelas.length) {
  return [{
    json: {
      erro: true,
      pular_busca_prestacao_oficial: true,
      motivo_pular_busca_prestacao_oficial: 'sem_tabelas_facta',
      mensagem: 'Facta não retornou tabelas em operacoes-disponiveis.',
      tabelas,
    }
  }];
}

// Política liberou prazo menor que o menor prazo das tabelas GOLD (24x): não existe tabela possível.
if (!Object.keys(ranking).length) {
  return [{
    json: {
      erro: true,
      pular_busca_prestacao_oficial: true,
      motivo_pular_busca_prestacao_oficial: 'prazo_politica_incompativel',
      mensagem: 'Prazo máximo da política não comporta nenhuma tabela GOLD.',
      tabelas,
    }
  }];
}

function numeroTabela(nomeTabela) {
  const match = String(nomeTabela || '').trim().match(/^(\d+)/);
  return match ? match[1] : '';
}

function tabelaValida(t) {
  return t && t.codigoTabela && t.tabela && t.prazo && t.coeficiente && t.parcela && t.valor_liquido;
}

function posicaoNoRanking(t) {
  const lista = ranking[Number(t.prazo)] || [];
  return lista.findIndex(r => r.codigo === numeroTabela(t.tabela));
}

function temSeguro(t) {
  return Number(t.valor_seguro || 0) > 0;
}

// Só GOLD da allowlist do cliente (por prazo) e, se exigido, COM seguro.
const candidatas = tabelas
  .filter(tabelaValida)
  .filter(t => posicaoNoRanking(t) >= 0)
  .filter(t => !exigirSeguro || temSeguro(t));

if (!candidatas.length) {
  const resumo = {};
  tabelas.forEach(t => {
    const cod = numeroTabela(t.tabela);
    if (!resumo[cod]) resumo[cod] = { prazos: [], com_seguro: false };
    resumo[cod].prazos.push(Number(t.prazo));
    if (temSeguro(t)) resumo[cod].com_seguro = true;
  });

  return [{
    json: {
      erro: true,
      pular_busca_prestacao_oficial: true,
      motivo_pular_busca_prestacao_oficial: 'sem_tabela_gold_com_seguro',
      mensagem: 'Nenhuma tabela GOLD com seguro disponível na resposta da Facta.',
      codigos_retornados: resumo,
      tabelas,
    }
  }];
}

// A busca da prestação oficial usa 1 tabela só: a do maior prazo e, nele, a de maior comissão.
candidatas.sort((a, b) => {
  const prazoB = Number(b.prazo);
  const prazoA = Number(a.prazo);
  if (prazoB !== prazoA) return prazoB - prazoA;
  return posicaoNoRanking(a) - posicaoNoRanking(b);
});

const escolhida = candidatas[0];
const posicao = posicaoNoRanking(escolhida);
const comissaoEscolhida = ranking[Number(escolhida.prazo)][posicao].comissao;

return [{
  json: {
    erro: false,
    pular_busca_prestacao_oficial: false,

    codigo_base_esperado: numeroTabela(escolhida.tabela),
    tabela_escolhida: escolhida.tabela,
    codigo_tabela: Number(escolhida.codigoTabela),
    prazo: Number(escolhida.prazo),
    coeficiente: Number(escolhida.coeficiente),
    valor_operacao: Number(escolhida.valor_liquido),
    valor_parcela: Number(escolhida.parcela),

    tem_seguro: temSeguro(escolhida),
    comissao_escolhida: comissaoEscolhida,

    total_tabelas: tabelas.length,
    total_candidatas: candidatas.length,

    tabelas,
  }
}];

